#define _GNU_SOURCE
#include <errno.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <sys/resource.h>
#include <sys/syscall.h>
#include <unistd.h>

struct MapAttr {
    uint32_t type, key_size, value_size, max_entries, flags, inner_map_fd, numa_node;
    char name[16];
    uint32_t ifindex, btf_fd, btf_key_type_id, btf_value_type_id, btf_vmlinux_value_type_id;
    uint64_t map_extra;
};

static int snapshot(unsigned batch) {
    FILE *file = fopen("/proc/meminfo", "r");
    char line[256];
    long vmalloc = -1;
    if (!file) return -1;
    while (fgets(line, sizeof line, file)) {
        char name[64]; long kib;
        if (sscanf(line, "%63s %ld kB", name, &kib) != 2) continue;
        if (!strcmp(name, "VmallocUsed:")) vmalloc = kib;
        if (!strcmp(name, "VmallocUsed:") || !strcmp(name, "MemFree:") ||
            !strcmp(name, "MemAvailable:") || !strcmp(name, "Slab:") ||
            !strcmp(name, "MemTotal:"))
            printf("{\"bpf_memory\":true,\"batch\":%u,\"name\":\"%s\",\"kib\":%ld}\n", batch, name, kib);
    }
    fclose(file);
    return vmalloc;
}

static int array(void) {
    struct MapAttr attr = {.type = 2, .key_size = 4, .value_size = 4, .max_entries = 2};
    int fd = syscall(SYS_bpf, 0, &attr, sizeof attr);
    if (fd < 0) return -1;
    return close(fd);
}

int main(void) {
    setbuf(stdout, NULL);
    struct rlimit limit = {1UL << 30, 1UL << 30};
    if (setrlimit(RLIMIT_MEMLOCK, &limit) || array()) return 90;
    printf("{\"bpf_array_control\":true,\"page_bytes\":%ld,\"uid\":%u}\n", sysconf(_SC_PAGESIZE), getuid());
    if (snapshot(0) < 0) return 91;
    long baseline = -1;
    for (unsigned batch = 1; batch <= 5; ++batch) {
        unsigned rounds = batch == 1 ? 16 : 128;
        for (unsigned type_index = 0; type_index < 2; ++type_index) {
            unsigned type = type_index == 0 ? 27 : 31;
            for (unsigned i = 0; i < 3; ++i) {
                unsigned sizes[] = {4096, 32768, 4194304};
                for (unsigned round = 0; round < rounds; ++round) {
                    struct MapAttr attr = {.type = type, .max_entries = sizes[i]};
                    errno = 0;
                    int fd = syscall(SYS_bpf, 0, &attr, sizeof attr);
                    int error = errno;
                    if (fd >= 0) { close(fd); return 92; }
                    if (error != ENOMEM) { printf("unexpected errno=%d type=%u\n", error, type); return 93; }
                }
                printf("{\"bpf_ringbuf_batch\":true,\"batch\":%u,\"type\":%u,\"bytes\":%u,\"rounds\":%u,\"errno\":%d}\n", batch, type, sizes[i], rounds, ENOMEM);
            }
        }
        if (array()) return 94;
        usleep(20000);
        long current = snapshot(batch);
        if (current < 0) return 91;
        if (batch == 1) baseline = current;
        if (current > baseline) return 95;
    }
    printf("{\"bpf_failure_cleanup\":true,\"post_warmup_vmalloc_growth\":false,\"array_after\":true}\n");
    return 0;
}
